//go:build amd64

package gf256

import "golang.org/x/sys/cpu"

// Region kernels generated by go-asmgen (gen/main.go) into gf256_amd64.s. They
// process the first n bytes: n is a multiple of 32 (16 for SSSE3). m is the
// affine matrix of the constant, tbl its split nibble table.
func mulGFNI(dst, src []byte, m uint64, n int)
func mulAddGFNI(dst, src []byte, m uint64, n int)
func mulAVX2(dst, src []byte, tbl *[32]byte, n int)
func mulAddAVX2(dst, src []byte, tbl *[32]byte, n int)
func mulSSSE3(dst, src []byte, tbl *[32]byte, n int)
func mulAddSSSE3(dst, src []byte, tbl *[32]byte, n int)

// cpuidGFNI reads CPUID.(7,0):ECX[8]; x/sys/cpu records it only under AVX-512.
func cpuidGFNI() (ok int)

func archTiers() (t []tier) {
	if cpu.X86.HasAVX2 && cpuidGFNI() != 0 {
		// Hosted CI runners and QEMU lack GFNI, so this kernel is executed
		// only on hardware that has it; the self-check keeps a mistake there
		// from ever returning wrong bytes (the tier is simply not offered).
		g := tier{"gfni+avx2",
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 31
				if n > 0 {
					mulGFNI(dst, src, mat[c], n)
				}
				return n
			},
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 31
				if n > 0 {
					mulAddGFNI(dst, src, mat[c], n)
				}
				return n
			}}
		if selfCheck(g) {
			t = append(t, g)
		}
	}
	if cpu.X86.HasAVX2 {
		t = append(t, tier{"avx2",
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 31
				if n > 0 {
					mulAVX2(dst, src, &nib[c], n)
				}
				return n
			},
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 31
				if n > 0 {
					mulAddAVX2(dst, src, &nib[c], n)
				}
				return n
			}})
	}
	if cpu.X86.HasSSSE3 {
		t = append(t, tier{"ssse3",
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 15
				if n > 0 {
					mulSSSE3(dst, src, &nib[c], n)
				}
				return n
			},
			func(dst, src []byte, c byte) int {
				n := len(src) &^ 15
				if n > 0 {
					mulAddSSSE3(dst, src, &nib[c], n)
				}
				return n
			}})
	}
	return t
}
